-- Sample auctions with pictures. Generated by scripts/generate-seed.mjs; do not edit by hand.
-- Prerequisite: run 0001_schema.sql and seed.sql, then sign up once in the app.
-- The first account becomes the seller of these listings. Safe to run again (skips titles that exist).
-- Pictures are served from /public/seed on your own site, so deploy the app before expecting them to show.

do $$
declare seller uuid;
begin
  select id into seller from public.profiles order by created_at limit 1;
  if seller is null then
    raise exception 'Sign up in the app first so there is a seller account, then run this again.';
  end if;

  insert into public.auctions
    (seller_id, category_id, title, description, images, condition, city, start_price, open_to_highest,
     reserve_price, mode, ends_at, current_price, deposit_amount)
  select seller, c.id, v.title, v.description, v.images, v.condition, v.city, v.start_price, v.open_to_highest,
         v.reserve, v.mode::auction_mode, v.ends_at, v.start_price, v.deposit
  from (values
    ('iPhone 13 128GB, battery 91%', 'Midnight color, original box and charger. Battery health 91%, no cracks, tiny scuff on the frame. Face ID and cameras fully working. Unlocked, Egyptian warranty expired.', 'phones', array['/seed/iphone-13-1.svg', '/seed/iphone-13-2.svg', '/seed/iphone-13-3.svg'], 'used', 'Cairo', 14000, false, 15000, 'timed', now() + interval '48 minutes', 140.00),
    ('Nike Dunk Low Panda, size 43, deadstock', 'Never worn, comes with original box and receipt. Size EU 43 / US 9.5. Verified purchase from an official retailer.', 'fashion', array['/seed/nike-dunk-panda-1.svg', '/seed/nike-dunk-panda-2.svg'], 'new', 'Giza', 3500, false, null, 'timed', now() + interval '150 minutes', 35.00),
    ('PlayStation 5 + 2 controllers', 'Disc edition, 825GB. Two DualSense controllers, HDMI and power cables. Used for six months, still under shop warranty until March.', 'gaming', array['/seed/ps5-bundle-1.svg', '/seed/ps5-bundle-2.svg', '/seed/ps5-bundle-3.svg'], 'like_new', 'Alexandria', 18000, false, 20000, 'timed', now() + interval '300 minutes', 180.00),
    ('Vintage Omega Seamaster 1968', 'Automatic, 34mm steel case, original dial with even patina. Serviced last year, keeps good time. Strap is not original.', 'watches', array['/seed/omega-seamaster-1.svg', '/seed/omega-seamaster-2.svg', '/seed/omega-seamaster-3.svg'], 'used', 'Cairo', 25000, false, 38000, 'timed', now() + interval '540 minutes', 250.00),
    ('Leather sofa, 3 seater, barely used', 'Genuine brown leather, 210cm wide. Moving abroad so it must go. Buyer collects from Maadi. Open to the highest bidder, no reserve.', 'home', array['/seed/leather-sofa-1.svg', '/seed/leather-sofa-2.svg'], 'like_new', 'Cairo', 1, true, null, 'timed', now() + interval '1560 minutes', 0.01),
    ('Samsung 55" QLED 4K TV', '2023 model, 4K 120Hz, smart apps. Remote and wall mount included. Screen is perfect.', 'electronics', array['/seed/samsung-qled-1.svg', '/seed/samsung-qled-2.svg'], 'like_new', 'Mansoura', 9000, false, null, 'timed', now() + interval '1800 minutes', 90.00),
    ('Egyptian 1 pound silver coin, 1938', 'King Farouk era silver pound, good detail on both faces. Kept in a coin album since the 1970s.', 'collectibles', array['/seed/silver-coin-1938-1.svg', '/seed/silver-coin-1938-2.svg'], 'used', 'Cairo', 800, false, null, 'timed', now() + interval '2880 minutes', 8.00),
    ('Mountain bike, 27.5", Shimano gears', 'Aluminium frame, 21 speed, front suspension, disc brakes. New tires this month. Suits riders 170 to 185cm.', 'sports', array['/seed/mountain-bike-1.svg', '/seed/mountain-bike-2.svg'], 'used', 'Giza', 4000, false, null, 'timed', now() + interval '4200 minutes', 40.00),
    ('Set of 6 hand-painted Khan el-Khalili plates', 'Hand-painted ceramic, 22cm each, signed by the artist. Each plate is slightly different. Starting at EGP 1.', 'collectibles', array['/seed/khan-plates-1.svg', '/seed/khan-plates-2.svg'], 'new', 'Cairo', 1, true, null, 'timed', now() + interval '192 minutes', 0.01),
    ('MacBook Air M1, 8GB / 256GB', 'Space grey, 212 battery cycles, no dents. Charger included. Fresh macOS install, ready to set up.', 'electronics', array['/seed/macbook-air-m1-1.svg', '/seed/macbook-air-m1-2.svg', '/seed/macbook-air-m1-3.svg'], 'used', 'Cairo', 24000, false, 26000, 'timed', now() + interval '720 minutes', 240.00),
    ('Toyota Corolla 2015, one owner', 'Automatic, 98,000 km, full service history at the agency. Licence valid until 2027. Open-ended: the seller will close when happy with the bid.', 'cars', array['/seed/corolla-2015-1.svg', '/seed/corolla-2015-2.svg', '/seed/corolla-2015-3.svg'], 'used', 'Alexandria', 380000, false, 420000, 'open_ended', null, 3800.00),
    ('Adidas Samba OG, size 42', 'Cloud white and black, brand new in box. Bought the wrong size.', 'fashion', array['/seed/adidas-samba-1.svg', '/seed/adidas-samba-2.svg'], 'new', 'Tanta', 2200, false, null, 'timed', now() + interval '1200 minutes', 22.00),
    ('Samsung Galaxy S23 Ultra 256GB', 'Phantom black, S Pen included. Screen protector since day one. Box and fast charger included.', 'phones', array['/seed/galaxy-s23-1.svg', '/seed/galaxy-s23-2.svg', '/seed/galaxy-s23-3.svg'], 'like_new', 'Giza', 30000, false, null, 'timed', now() + interval '960 minutes', 300.00),
    ('Seiko 5 automatic, blue dial', 'Stainless steel bracelet, 100m water resistance, automatic movement. Worn a handful of times.', 'watches', array['/seed/rolex-style-watch-1.svg', '/seed/rolex-style-watch-2.svg'], 'like_new', 'Cairo', 3000, false, null, 'timed', now() + interval '420 minutes', 30.00),
    ('Umm Kulthum vinyl collection, 8 records', 'Eight Egyptian-pressed LPs from the 1960s and 70s. Sleeves show age, records play cleanly. Open to highest bidder.', 'collectibles', array['/seed/vinyl-umm-kulthum-1.svg', '/seed/vinyl-umm-kulthum-2.svg'], 'used', 'Cairo', 1, true, null, 'timed', now() + interval '2160 minutes', 0.01),
    ('Ergonomic gaming chair, red and black', 'Adjustable arms, tilt lock and lumbar pillow. Eight months old, no tears.', 'gaming', array['/seed/gaming-chair-1.svg', '/seed/gaming-chair-2.svg'], 'used', 'Alexandria', 2500, false, null, 'timed', now() + interval '1320 minutes', 25.00),
    ('Solid wood dining table with 6 chairs', 'Beech wood, 180 x 90cm. Chairs have fabric seats in good condition. Buyer arranges pickup.', 'home', array['/seed/dining-table-1.svg', '/seed/dining-table-2.svg', '/seed/dining-table-3.svg'], 'used', 'Giza', 6000, false, null, 'timed', now() + interval '3120 minutes', 60.00),
    ('Cycling set: helmet, lights, bike computer', 'Giro helmet size M, front and rear USB lights, GPS bike computer. Barely used.', 'sports', array['/seed/road-bike-helmet-set-1.svg', '/seed/road-bike-helmet-set-2.svg'], 'like_new', 'Cairo', 1200, false, null, 'timed', now() + interval '2640 minutes', 12.00),
    ('iPad Pro 11" (2021) + Apple Pencil 2', '128GB Wi-Fi, space grey. Pencil 2 works perfectly. Includes folio case.', 'phones', array['/seed/ipad-pro-1.svg', '/seed/ipad-pro-2.svg', '/seed/ipad-pro-3.svg'], 'used', 'Cairo', 20000, false, 21000, 'timed', now() + interval '1680 minutes', 200.00),
    ('Polaroid OneStep+ instant camera', 'Bluetooth app control, rechargeable battery. Two unopened film packs included.', 'electronics', array['/seed/polaroid-camera-1.svg', '/seed/polaroid-camera-2.svg'], 'like_new', 'Mansoura', 1800, false, null, 'timed', now() + interval '1080 minutes', 18.00)
  ) as v(title, description, cat, images, condition, city, start_price, open_to_highest, reserve, mode, ends_at, deposit)
  join public.categories c on c.slug = v.cat
  where not exists (select 1 from public.auctions a where a.seller_id = seller and a.title = v.title);
end $$;
